 'github-token':r'\\b(?:gh[pousr]_[A-Za-z0-9]{30,255}|github_pat_[A-Za-z0-9_]{40,255})\\b',
 'huggingface-token':r'\\bhf_[A-Za-z0-9]{30,255}\\b',
