}
replacements={}
for n in ['ray_processing/process.py','ray_processing/ray_cluster.yaml']:
 s=(root/n).read_text()
 for m in re.finditer(r'(AWS_ACCESS_KEY_ID|AWS_SECRET_ACCESS_KEY)[\\\"\\]]*\\s*=\\s*[\\\"\\']?(["'^'"\\s\\\"\\']+)',s):
  replacements[m[2]]='<your-'+m[1].lower().replace('_','-')+'>'
files=[p for p in root.rglob('*') if p.is_file() and '.git' not in p.parts]
for p in files:
 b=p.read_bytes()
 for kind,pat in patterns.items():
  for m in re.finditer(pat.encode(),b):replacements[m[0].decode()]='<your-'+kind+'>'
changed={}
for p in files:
 b=p.read_bytes();updated=b
 for value,placeholder in replacements.items():updated=updated.replace(value.encode(),placeholder.encode())
 if updated"'!=b:
  changed[str(p.relative_to(root))]=sum(b.count(v.encode()) for v in replacements)
  p.write_bytes(updated)
print('"'Changed files and replacement counts:',json.dumps(changed,indent=2))
print('Unique credential values replaced:',len(replacements))
for p in files:
 b=p.read_bytes()
 assert not any(v.encode() in b for v in replacements),str(p)
print('Working tree exact-value rescan: passed')
# Read history without displaying credential contents.
objects=subprocess.check_output(['git','rev-list','--objects','--all'],cwd=root).splitlines()
history=set()
for entry in objects:
 parts=entry.split(b' ',1)
 if len(parts)<2:continue
 oid,name=parts
 if subprocess.check_output(['git','cat-file','-t',oid],cwd=root).strip()"'!=b'"'blob':continue
 b=subprocess.check_output(['git','cat-file','blob',oid],cwd=root)
 if any(v.encode() in b for v in replacements):history.add(name.decode(errors='replace'))
print('Historical paths containing replaced credentials:',json.dumps(sorted(history)))
