import pathlib,re,gzip,zipfile,ast
s=pathlib.Path('eval/eval_openlm_ckpt.py').read_text();tree=ast.parse(s)
pw=[]
for node in ast.walk(tree):
 if isinstance(node,ast.List):
  vals=[n.value for n in node.elts if isinstance(n,ast.Constant) and isinstance(n.value,str)]
  if '-P' in vals:pw.append(vals[vals.index('-P')+1].encode())
pat=re.compile(rb'(?:AKIA|ASIA)[A-Z0-9]{16}|gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{40,}|hf_[A-Za-z0-9]{30,}|sk-(?:proj-|ant-)?[A-Za-z0-9_-]{20,}|AIza[A-Za-z0-9_-]{35}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----')
count=0;skipped=[]
for p in pathlib.Path('.').rglob('*'):
 if not p.is_file() or '.git' in p.parts:continue
 b=p.read_bytes();assert not pat.search(b),str(p)
 if b.startswith(b'\\x1f\\x8b'):
  assert not pat.search(gzip.decompress(b)),str(p);count+=1
 elif zipfile.is_zipfile(p):
  with zipfile.ZipFile(p) as z:
   for n in z.namelist():
    try:b=z.read(n,pwd=pw[0] if pw else None)
    except RuntimeError:skipped.append(str(p)+':'+n);continue
    assert not pat.search(b),str(p)+':'+n
  count+=1
print('Credential-pattern scan passed; archives checked:',count,'; skipped:',skipped)
print('Broad-scan candidate:',pathlib.Path('tests/baselines/mappers/modifiers/test_modifiers.py').read_text().splitlines()[588])
